INSERT INTO `spa_comments` (`id`, `iduser`, `idsale`, `text`, `rate`, `added`) VALUES
(1, 5, 9, 'La experiencia fue increíble!!! ', 5, '2017-09-13 16:41:43'),
(2, 412, 107, 'El lugar espectacular, la atención muy buena y los masajes expectaculares! \nSeguramente volveremos!!', 5, '2018-02-17 19:31:00'),
(3, 544, 139, 'Una experiencia única, realmente salimos relajadas, nos desconectamos de todo por un rato y nos predispusimos a disfrutar, y fue muy placentero. El ambiente, los masajes, las piedras, excelentes,muy conforme!', 5, '2018-06-04 22:28:23'),
(4, 509, 146, 'La experiencia fue muy buena y cumplieron con todas las condiciones .\nTotalmente recomendado.', 4, '2018-06-13 14:09:22'),
(5, 551, 144, 'super amables una atencion divina y apartur de ahora solo me atendere con ellos c9n todo tipo de tratamientos', 5, '2018-06-13 15:27:21'),
(6, 527, 133, 'La experiencia fue increíble. Desde el primer llamado al Hotel, siempre me respondieron amablemente y me respondieron todas las consultas. Llegamos y la mesa para el Té estaba lista. El té estaba compuesto por bebidas frías y calientes y comida dulce y salada. Luego fuimos al Spa en el subsuelo, estuvimos disfrutando las instalaciones mientras nos hacíamos los masajes. Recomendable!', 5, '2018-07-02 13:59:39'),
(7, 583, 157, 'Super completo! Y la atención fue buenisima. ', 5, '2018-07-16 08:19:20'),
(8, 629, 166, 'Excelente atención, pasamos una tarde super relajada.  ', 5, '2018-07-27 09:27:42'),
(9, 556, 147, 'Nos encanto!la pasamos genial y salimos super relajadas!la atencion y todos los masajes excelentes!lo super recomiendo!', 5, '2018-08-07 18:12:57'),
(10, 684, 186, 'todo  perfecto, el lugar y la atencion muy buenos, super recomendable', 5, '2018-09-13 09:40:30'),
(11, 943, 303, 'Muy lindo para compartir con mi mujer. Es la primera vez que hacemos masajes. ', 4, '2018-12-29 21:34:02'),
(12, 1006, 334, 'Todo bien!', 4, '2019-04-22 19:15:24');
INSERT INTO `spa_config` (`id`, `name`, `value`) VALUES
(1, 'title', 'Spa. Estetica. Centros de Estética. Centros Integrales de Estética y Medicina, Tratamientos de Estetica. Estilo Spa'),
(2, 'description', 'EstiloSpa, El Portal lider en promocionar Spa, centros de Estetica, Centros de Medicina Estetica, Centros de Belleza, Clinica. Cumple 8 Años online, desde sus inicios, trabaja promocionando y dando a conocer a todos los cibernautas, las diferentes opciones en spa, Centros de Estetica; Centros de Belleza; Medicina Estetica, clinicas, Masajes; todo lo relacionado con el Relax, Bienestar y la Estetica Facial y Corporal.'),
(3, 'phones', '[\"011 4643 0556\"]'),
(4, 'mails', '[\"estilospa.com@gmail.com\"]'),
(5, 'keywords', 'Spa, estetica, medicina, cirugia, masajes, tratamientos, centros de estetica, medicina estetica, cirugia estetica, masajes, tratamientos faciales, tratamientos corporales'),
(6, 'maintenance', '0');
