INSERT INTO `spa_promos` (`id`, `idclient`, `idpromotype`, `sale`, `stores`, `title`, `subtitle`, `description`, `includes`, `duration`, `recomendations`, `reservation`, `cancellation`, `gallery`, `price`, `discount`, `amount`, `start`, `finish`, `added`, `views`, `deleted`, `position`, `position_client`) VALUES
(19, 16, 2, 1, '674', '2x1 en Masajes y Presoterapia', 'Veni con una amiga a una sesión de masajes + presoterapia', 'Veni con una amiga a una sesión de masajes + presoterapia\nSOLO PAGA UNA', 'gdfg', 'dfgdf', 'fdgd', 'fgdf', 'gfgf', '[{\"photoname\":\"masajes-720x340-9501\",\"extension\":\"jpg\"}]', 2000, 0, 20, '2017-06-01', '2019-06-28', '2017-07-14 18:12:34', 0, 0, 470, 0),
(26, 24, 1, 1, '', '60% OFF en Depilación Definitiva Pack 12 sesiones', 'aa', 'ss', '', '', '', '', '', '[{\"photoname\":\"depi4ever-1309\",\"extension\":\"jpg\"}]', 20, 60, 20, '2017-06-01', '2017-06-30', '2017-07-14 18:12:34', 0, 0, 477, 0),
(34, 33, 1, 1, '', 'SPA DETOX 30% Off', 'Una opción tanto para hombre o mujer', '*Sillón masajeador\n*Infusión de té\n*Exfoliación corporal de chocolate y nuez en mini sauna (remoción de células muertas)\n*Masaje descontracturante con aplicación de piedras calientes\n*Masaje capilar\n*Exfoliación facial\n*Masaje facial relajante\n*Mascara descongestiva (refrescante)\n*Parafina en manos\n\nDuración 2:40hs\nTOTAL $670.-', '', '', '', '', '', '[{\"photoname\":\"carlalevy-promo-6-3246\",\"extension\":\"jpg\"}]', 670, 30, 20, '2017-06-01', '2017-06-30', '2017-07-14 18:12:34', 0, 0, 483, 0),
(35, 33, 1, 1, '', '20% Off PACK MASAJES x 5 ', 'Pack Masaje Descontracturante', 'Pack Masaje Descontracturante \n5 Sesiones $1500.-', '', '', '', '', '', '[{\"photoname\":\"carlalevy-promo-7-4652\",\"extension\":\"jpg\"}]', 1500, 20, 20, '2017-06-01', '2017-06-30', '2017-07-14 18:12:34', 0, 0, 484, 0),
(36, 33, 1, 1, '', '30% OFF PEELING QUIMICO', '5 SESIONES', 'Se trata de la aplicación de una solución química, destinada a mejorar y suavizar la textura de la piel facial, ya que elimina sus capas exteriores dañadas. A menudo se utilizan para este fin los alfa-hidroxiácidos. El mismo pude ser semanal, logrando una recuperación excelente.\nSe recomienda para el tratamiento de acné por su actividad antiséptica. Asimismo se logra muy buenos resultados en pieles foto-envejecidas.', '', '', '', '', '', '[{\"photoname\":\"carlalevy-promo-8-5097\",\"extension\":\"jpg\"}]', 1400, 30, 20, '2017-06-01', '2017-06-30', '2017-07-14 18:12:34', 0, 0, 485, 0),
(37, 33, 1, 1, '', 'PACK DRENAJE LINFÁTICO MANUAL', '5 sesiones - 50 minutos cada uno', 'Es tal vez la técnica más efectiva para ayudar al sistema circulatorio de retorno tanto venoso como linfático, favorece la re-absorción de sobrecargas líquidas.\nIndicado para:\n-Embarazadas\n-Problemas circulatorios\n-Celulitis\n– Post Liposucción.', '', '', '', '', '', '[{\"photoname\":\"carlalevy-promo-9-9894\",\"extension\":\"jpg\"}]', 1300, 0, 20, '2017-06-01', '2017-06-30', '2017-07-14 18:12:34', 0, 0, 486, 0),
(38, 33, 1, 1, '', '30% OFF en SHOCK FACIAL', 'Promo facial', 'Limpieza de cutis profunda + Microdermoabrasion (punta de diamante)  + \nMascara Descongestiva', '', '', '', '', '', '[{\"photoname\":\"carlalevy-promo-10-8120\",\"extension\":\"jpg\"}]', 550, 0, 20, '2017-06-01', '2017-06-30', '2017-07-14 18:12:34', 0, 0, 488, 0),
